// Revisa que el aviso de la API traiga todo lo necesario antes de llamar a Zoho CRM.
// Se ejecuta una vez por cada aviso que llega al webhook.
const cuerpo = $json.body ?? {};
const pedido = cuerpo.pedido ?? {};
const cliente = cuerpo.cliente ?? {};
const errores = [];

if (cuerpo.evento !== 'pedido.creado') errores.push('El evento debe ser pedido.creado');
if (!Number.isInteger(pedido.id_pedido) || pedido.id_pedido <= 0) errores.push('Falta el id del pedido');
if (typeof cliente.nombre !== 'string' || cliente.nombre.trim() === '') errores.push('Falta el nombre del cliente');
if (typeof cliente.email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cliente.email.trim())) {
  errores.push('El correo del cliente no es válido');
}
if (!Array.isArray(pedido.detalle) || pedido.detalle.length === 0) errores.push('El pedido no tiene productos');
if (typeof pedido.total !== 'number' || pedido.total <= 0) errores.push('El total del pedido debe ser mayor que 0');

// Zoho pide el apellido (Last_Name). "Ana Gómez" queda como nombre "Ana" y apellido "Gómez"
const partes = String(cliente.nombre ?? '').trim().split(/\s+/);
const nombre = partes.length > 1 ? partes[0] : '';
const apellido = partes.length > 1 ? partes.slice(1).join(' ') : partes[0];

const pesos = new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 });
const total = typeof pedido.total === 'number' ? pesos.format(pedido.total) : '';
const productos = Array.isArray(pedido.detalle) ? pedido.detalle : [];

return {
  json: {
    valido: errores.length === 0,
    errores,
    id_pedido: Number.isInteger(pedido.id_pedido) ? pedido.id_pedido : null,
    pedido: { ...pedido, total_texto: total },
    cliente: {
      nombre: cliente.nombre ?? '',
      email: String(cliente.email ?? '').trim().toLowerCase(),
      ciudad: cliente.ciudad ?? '',
      nombre_zoho: nombre,
      apellido_zoho: apellido
    },
    // Lo que se escribe en el campo Descripción del contacto en Zoho
    descripcion_zoho: `Último pedido: #${pedido.id_pedido} del ${pedido.fecha} por ${total} (${productos.length} ${productos.length === 1 ? 'producto' : 'productos'})`,
    lineas_correo: productos.map((linea) => `- ${linea.cantidad} x ${linea.producto} = ${pesos.format(linea.subtotal)}`)
  }
};

// Revisa lo que respondió Zoho y arma la fila del log y el correo.
// Si Zoho no dice "success", se lanza un error y el item sigue por la salida de error.
const aviso = $('Validar pedido').item.json;
const fila = $json.body?.data?.[0];

if (fila?.status !== 'success') {
  throw new Error(`Zoho no guardó el contacto: ${fila?.code ?? 'sin código'} ${fila?.message ?? ''}`.trim());
}

const resultado = $('Crear contacto').isExecuted ? 'creado' : 'actualizado';
const verbo = resultado === 'creado' ? 'se creó' : 'se actualizó';

return {
  json: {
    id_pedido: aviso.id_pedido,
    resultado,
    email_cliente: aviso.cliente.email,
    id_externo: String(fila.details.id),
    mensaje: `Contacto ${resultado} en Zoho CRM con el pedido #${aviso.id_pedido}`,
    asunto: `Pedido #${aviso.id_pedido}: el contacto ${verbo} en Zoho CRM`,
    texto: [
      `Se procesó el pedido #${aviso.id_pedido} del ${aviso.pedido.fecha}.`,
      '',
      `Cliente: ${aviso.cliente.nombre} (${aviso.cliente.email}), ${aviso.cliente.ciudad}`,
      `Total: ${aviso.pedido.total_texto}`,
      'Productos:',
      ...aviso.lineas_correo,
      '',
      `Zoho CRM: el contacto ${verbo} (id ${fila.details.id}).`,
      '',
      'Este correo lo envió n8n con el workflow Pedido a Zoho CRM.'
    ].join('\n')
  }
};

// Algo falló al hablar con Zoho (no responde, el token no sirve, rechazó los datos...).
// $json.error trae lo que pasó. Se registra como error y se avisa por correo.
const aviso = $('Validar pedido').item.json;
const error = typeof $json.error === 'string' ? { message: $json.error } : ($json.error ?? {});

// error.cause.message trae el código HTTP y lo que respondió Zoho, por ejemplo:
// 401 - "{\"code\":\"INVALID_TOKEN\",\"message\":\"invalid oauth token\",...}"
const causa = String(error.cause?.message ?? '');
const codigoHttp = causa.match(/^(\d{3}) - /)?.[1];
let codigoZoho;
try {
  let respuesta = JSON.parse(causa.replace(/^\d{3} - /, ''));
  if (typeof respuesta === 'string') respuesta = JSON.parse(respuesta);
  codigoZoho = respuesta.code ?? respuesta.data?.[0]?.code;
} catch {
  // la causa no traía JSON
}
const detalle = [codigoHttp && `HTTP ${codigoHttp}`, codigoZoho, error.description || error.message]
  .filter(Boolean)
  .join(' · ') || 'Error desconocido';

return {
  json: {
    id_pedido: aviso.id_pedido,
    resultado: 'error',
    email_cliente: aviso.cliente.email,
    id_externo: null,
    mensaje: detalle.slice(0, 1000),
    asunto: `Error con el pedido #${aviso.id_pedido}: no se pudo pasar a Zoho CRM`,
    texto: [
      `No se pudo pasar el pedido #${aviso.id_pedido} a Zoho CRM.`,
      '',
      `Cliente: ${aviso.cliente.nombre} (${aviso.cliente.email})`,
      `Error: ${detalle}`,
      '',
      `Revisa la ejecución ${$execution.id} en n8n (Executions) y vuelve a intentarlo.`
    ].join('\n')
  }
};

// El aviso no pasó la validación: se registra como rechazado y no se llama a Zoho
const aviso = $json;
return {
  json: {
    id_pedido: aviso.id_pedido,
    resultado: 'rechazado',
    email_cliente: aviso.cliente.email || null,
    id_externo: null,
    mensaje: aviso.errores.join('; '),
    asunto: `Pedido ${aviso.id_pedido ? '#' + aviso.id_pedido : 'sin id'} rechazado: no se envió a Zoho CRM`,
    texto: [
      'El aviso de un pedido no pasó la validación y no se envió a Zoho CRM.',
      '',
      'Pedido: ' + (aviso.id_pedido ?? 'sin id'),
      'Correo del cliente: ' + (aviso.cliente.email || 'sin correo'),
      'Errores:',
      ...aviso.errores.map((error) => '- ' + error),
      '',
      'Ejecución de n8n: ' + $execution.id
    ].join('\n')
  }
};

